input.command:
mkdir -p /tmp/qa_tj && cat > /tmp/qa_tj/verify_formv5.py <<'EOF'
import csv, glob, hashlib, io, json, os, re, sys, zipfile
from pathlib import Path

REPO = Path(sys.argv[1])
EXP = REPO / "experiments/09_human_rating_collection"
PREP = REPO / "private/09_human_rating_collection/preparation_11-09-2026"
MAN = json.loads((PREP / "packets/FormV5/MANIFEST.json").read_text())
QUEUE = json.loads((PREP / "DISPATCH_QUEUE_FORM_V5.json").read_text())
SCHEMA = json.loads((EXP / "support/RATING_FORM_SCHEMA.json").read_text())
COLS = SCHEMA["columns"]
GUIDE = (EXP / "rating_task_packet/RATING_FORM_GUIDE.md").read_bytes()
URL_RE = re.compile(r"https?://[^\s)\]>\"']+")
problems = []
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()

queue_by_att = {q["attachment"]: q for q in QUEUE}
print(f"manifest entries: {len(MAN)}; queue entries: {len(QUEUE)}")
for e in MAN:
    tag = f"{e['rater_id']}/{Path(e['output']).name}"
    src, out = Path(e["source"]), Path(e["output"])
    if sha(src) != e["source_sha256"]: problems.append(f"{tag}: source sha mismatch")
    if sha(out) != e["output_sha256"]: problems.append(f"{tag}: output sha mismatch")
    q = queue_by_att.get(str(out))
    if q and q["attachment_sha256"] != e["output_sha256"]: problems.append(f"{tag}: queue attachment sha != manifest")
    zs, zo = zipfile.ZipFile(src), zipfile.ZipFile(out)
    S = {n: zs.read(n) for n in zs.namelist() if not n.endswith("/")}
    O = {n: zo.read(n) for n in zo.namelist() if not n.endswith("/")}
    sci_s = {n: b for n, b in S.items() if n.endswith((".lean", ".py"))}
    sci_o = {n: b for n, b in O.items() if n.endswith((".lean", ".py"))}
    if sci_s != sci_o: problems.append(f"{tag}: scientific payload differs: {set(sci_s)^set(sci_o)} or bytes")
    if len(sci_o) != e["preserved_scientific_files"]: problems.append(f"{tag}: preserved count {len(sci_o)} != {e['preserved_scientific_files']}")
    # members
    names = sorted(O)
    for bad in ("YOUR_RATING_SHEET.txt", "EMAIL_INSTRUCTIONS_V0.md"):
        if any(n.endswith(bad) for n in names): problems.append(f"{tag}: contains {bad}")
    rubric = "Rating_Instructions.md" if "Rating_Instructions.md" in O else ("human_judgements_prompt.md" if "human_judgements_prompt.md" in O else None)
    if rubric is None: problems.append(f"{tag}: no rubric file")
    else:
        rs, ro = S[rubric].decode(), O[rubric].decode()
        if rs.split("## Output format")[0] != ro.split("## Output format")[0]: problems.append(f"{tag}: rubric pre-output section changed")
        if rs.split("## Tie-break rule")[1] != ro.split("## Tie-break rule")[1]: problems.append(f"{tag}: rubric post-output section changed")
    if O.get("RATING_FORM_GUIDE.md") != GUIDE: problems.append(f"{tag}: RATING_FORM_GUIDE.md differs from repo current file")
    # ratings.csv
    rows = list(csv.DictReader(io.StringIO(O["ratings.csv"].decode())))
    hdr = next(csv.reader(io.StringIO(O["ratings.csv"].decode())))
    if hdr != COLS: problems.append(f"{tag}: ratings.csv header {hdr}")
    if len(rows) != e["candidate_count"]: problems.append(f"{tag}: rows {len(rows)} != candidate_count {e['candidate_count']}")
    for r in rows:
        if r["rater_name"] != e["rater_name"] or r["rater_id"] != e["rater_id"]: problems.append(f"{tag}: identity mismatch {r['rater_name']}/{r['rater_id']}")
        if any(r[c] for c in COLS[5:]): problems.append(f"{tag}: non-blank response {r['item_id']}")
        cf = r["candidate_file"]
        # candidate exists in zip?
