from pathlib import Path
REPO = Path(sys.argv[1]); EXP = REPO / "experiments/09_human_rating_collection"
PREP = REPO / "private/09_human_rating_collection/preparation_11-09-2026"
MAN = json.loads((PREP / "packets/FormV5/MANIFEST.json").read_text())
QUEUE = json.loads((PREP / "DISPATCH_QUEUE_FORM_V5.json").read_text())
SCHEMA = json.loads((EXP / "support/RATING_FORM_SCHEMA.json").read_text()); COLS = SCHEMA["columns"]
PATHMAP = json.loads((EXP / "support/WARMUP_PATHS.json").read_text())["paths"]
GUIDE = (EXP / "rating_task_packet/RATING_FORM_GUIDE.md").read_bytes()
URL_RE = re.compile(r"https?://[^\s)\]>\"']+")
problems = []
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def members(z):
    raw = {n: z.read(n) for n in z.namelist() if not n.endswith("/")}
    roots = {n.split("/")[0] for n in raw}
    root = next(iter(roots)) + "/" if len(roots) == 1 and all("/" in n for n in raw) else ""
    return {n[len(root):]: b for n, b in raw.items()}, root
queue_by_att = {q["attachment"]: q for q in QUEUE}
for e in MAN:
    tag = f"{e['rater_id']}/{Path(e['output']).name}"; src, out = Path(e["source"]), Path(e["output"])
    if sha(src) != e["source_sha256"]: problems.append(f"{tag}: source sha mismatch")
    if sha(out) != e["output_sha256"]: problems.append(f"{tag}: output sha mismatch")
    q = queue_by_att.get(str(out))
    if q and q["attachment_sha256"] != e["output_sha256"]: problems.append(f"{tag}: queue sha != manifest")
    S, sroot = members(zipfile.ZipFile(src)); O, oroot = members(zipfile.ZipFile(out))
    if oroot != out.stem + "/": problems.append(f"{tag}: zip root {oroot!r} != {out.stem}/")
    sci_s = {PATHMAP.get(n, n): b for n, b in S.items() if n.endswith((".lean", ".py"))}
    sci_o = {n: b for n, b in O.items() if n.endswith((".lean", ".py"))}
    if sci_s != sci_o: problems.append(f"{tag}: scientific payload differs (names {sorted(set(sci_s)^set(sci_o))[:3]})")
    if len(sci_o) != e["preserved_scientific_files"]: problems.append(f"{tag}: preserved count {len(sci_o)} != {e['preserved_scientific_files']}")
    for bad in ("YOUR_RATING_SHEET.txt", "EMAIL_INSTRUCTIONS_V0.md"):
        if any(n.endswith(bad) for n in O): problems.append(f"{tag}: contains {bad}")
    rubric = "Rating_Instructions.md" if "Rating_Instructions.md" in O else ("human_judgements_prompt.md" if "human_judgements_prompt.md" in O else None)
    if rubric is None: problems.append(f"{tag}: no rubric")
    else:
        rs, ro = S[rubric].decode(), O[rubric].decode()
        if rs.split("## Output format")[0] != ro.split("## Output format")[0]: problems.append(f"{tag}: rubric pre-output changed")
        if rs.split("## Tie-break rule")[1] != ro.split("## Tie-break rule")[1]: problems.append(f"{tag}: rubric post-output changed")
        if "## Current form headers" in ro: problems.append(f"{tag}: stale 'Current form headers' section")
    if O.get("RATING_FORM_GUIDE.md") != GUIDE: problems.append(f"{tag}: RATING_FORM_GUIDE.md stale vs repo")
    text_csv = O["ratings.csv"].decode(); hdr = next(csv.reader(io.StringIO(text_csv))); rows = list(csv.DictReader(io.StringIO(text_csv)))
    if hdr != COLS: problems.append(f"{tag}: header {hdr}")
    if len(rows) != e["candidate_count"]: problems.append(f"{tag}: rows {len(rows)} != {e['candidate_count']}")
    for r in rows:
        if (r["rater_name"], r["rater_id"]) != (e["rater_name"], e["rater_id"]): problems.append(f"{tag}: identity {r['rater_name']}/{r['rater_id']}")
        if any(r[c] for c in COLS[5:]): problems.append(f"{tag}: non-blank response {r['item_id']}")
        cf = r["candidate_file"]
        if not any(n == cf or n.endswith("/" + cf) for n in O): problems.append(f"{tag}: candidate_file {cf} not in zip")
        if r["task_folder"] not in {n.split("/")[0] for n in O}: problems.append(f"{tag}: task_folder {r['task_folder']} not in zip")
    urls = set()
    for n, b in O.items():
        if n.endswith((".md", ".txt", ".csv")): urls |= set(URL_RE.findall(b.decode(errors="replace")))
    gurls = {u for u in urls if "docs.google.com" in u}; allowed = {e["sheet_url"]} if e["sheet_url"] else set()
    if gurls - allowed: problems.append(f"{tag}: foreign sheet URLs {gurls - allowed}")
    if e["sheet_url"] and gurls != allowed: problems.append(f"{tag}: sheet URL set {gurls} != {allowed}")
    other = {u for u in urls if "docs.google.com" not in u}
    for line in O["FILES.sha256"].decode().splitlines():
        h, n = line.split("  ", 1)
        if n not in O or hashlib.sha256(O[n]).hexdigest() != h: problems.append(f"{tag}: FILES.sha256 wrong for {n}")
    listed = {l.split("  ",1)[1] for l in O["FILES.sha256"].decode().splitlines()}
    if listed != set(O) - {"FILES.sha256"}: problems.append(f"{tag}: FILES.sha256 coverage mismatch {set(O)-{'FILES.sha256'}-listed}")
    text = "\n".join(O[n].decode(errors="replace") for n in O if n.endswith((".md", ".txt")))
    for pat in ["Fill only", "seven columns", "required-only", "two fields", "only two", "model_assistance", "independent_rating", "lean_familiarity", "YOUR_RATING_SHEET", "Optional notes", "the only two", "no copy is needed" if not e["sheet_url"] else "\x00"]:
        if pat.lower() in text.lower(): problems.append(f"{tag}: stale wording '{pat}'")
    kind = "setN" if "setN" in out.name else "warmup"
    live = glob.glob(str(EXP / f"ratings/*__{kind}_{e['rater_id']}.csv")) or glob.glob(str(EXP / f"support/forms/*__{kind}_{e['rater_id']}.csv"))
    L = {r["item_id"]: r for r in csv.DictReader(open(live[0], newline=""))} if live else {}
    if not live: problems.append(f"{tag}: no live CSV")
    mism = 0
    for r in rows:
        lr = L.get(r["item_id"])
        if lr is None: problems.append(f"{tag}: item {r['item_id']} absent from live"); continue
        if (lr["task_folder"], lr["candidate_file"], lr["rater_name"]) != (r["task_folder"], r["candidate_file"], r["rater_name"]):
            mism += 1
            if mism <= 2: problems.append(f"{tag}: path/name mismatch {r['item_id']}: packet {r['task_folder']} | {r['candidate_file']} vs live {lr['task_folder']} | {lr['candidate_file']}")
    if kind == "warmup" and not e["sheet_url"]:
        if O["ratings.csv"] != (EXP / "support/forms/Slava_Naprienko__warmup_V01.csv").read_bytes(): problems.append(f"{tag}: Slava zip csv != support/forms csv")
    print(f"  {tag}: rubric={rubric} rows={len(rows)} live={Path(live[0]).name if live else None} live_rows={len(L)} mism={mism} members={len(O)} sci={len(sci_o)} other_urls={sorted(other)}")
print("PROBLEMS:" if problems else "NO PROBLEMS")
for p in problems: print(" -", p)
