import json, sys, csv
from pathlib import Path
EXP = Path(sys.argv[1]) / "experiments/09_human_rating_collection"
after = json.loads((EXP / "support/sheet_exports/11-11-2026_final_form/after.json").read_text())
def grid(a):
    rd = a["after"]["sheets"][0]["data"][0]["rowData"]
    out = []
    for r in rd:
        vals = [c.get("formattedValue", "") for c in r.get("values", [])]
        out.append(vals + [""] * (11 - len(vals)))
    return out
for a in after:
    rows = list(csv.reader(open(EXP / "ratings" / a["filename"], newline="")))
    g = grid(a)
    hdr_ok = g[0][:11] == rows[0]
    body_ok = [r[:11] for r in g[1:1+len(rows)-1]] == rows[1:]
    extra = [r for r in g[len(rows):] if any(r)]
    exp_ok = rows[1:] == a["expected"]
    print(f"{a['filename']}: readback_header_ok={hdr_ok} readback_body_ok={body_ok} extra_nonblank_rows={len(extra)} expected_ok={exp_ok} verified={a['verified']}")
    if not exp_ok or not body_ok:
        for i, (c, e) in enumerate(zip(rows[1:], a["expected"])):
            if c != e:
                for j, (x, y) in enumerate(zip(c, e)):
                    if x != y: print(f"   row {i+1} col {j} ({rows[0][j]}): csv={x!r} expected={y!r}")
        for i, (c, r) in enumerate(zip(rows[1:], g[1:])):
            if c != r[:11]:
                for j, (x, y) in enumerate(zip(c, r)):
                    if x != y: print(f"   row {i+1} col {j} ({rows[0][j]}): csv={x!r} readback={y!r}")
    # data validation on cells row 2
    if a["filename"].startswith("Yegor"):
        r2 = a["after"]["sheets"][0]["data"][0]["rowData"][1].get("values", [])
        for j, c in enumerate(r2):
            dv = c.get("dataValidation")
            if dv: print(f"   validation col {j}: {dv.get('condition',{}).get('type')} {[v.get('userEnteredValue') for v in dv.get('condition',{}).get('values',[])]} strict={dv.get('strict')}")
EOF

